function createSubmissionKey():string{if(typeof crypto==="undefined"||typeof crypto.randomUUID!=="function")throw new Error("Secure submission is unavailable in this browser. Please reload and try again.");return crypto.randomUUID()+crypto.randomUUID();}
function impactLabel(model?:string):string|null {return model==="pro_bono"?"100% Pro-Bono / Impact":model==="community_discount"?"Community Discounted Rate":model==="capacity_grant"?"Capacity Grant":null;}
function lifecycleLabel(service:{lifecycle_status?:string;expires_at?:string|null}):string {const status=service.lifecycle_status||"active";if(status==="active")return service.expires_at?"Active until "+new Date(service.expires_at).toLocaleDateString():"Ongoing · no expiry";if(status==="pending_review")return "Under review";if(status==="fulfilled")return "Fulfilled";if(status==="archived")return "Archived";if(status==="paused")return "Paused";if(status==="suspended")return "Temporarily suspended";return status.replaceAll("_"," ");}
function priceLabel(service:{pricing_model:string;price_amount?:number|string|null;currency?:string|null}):string {if(service.pricing_model==="quote")return "Request a quote";if(service.pricing_model==="free")return "Free";return service.price_amount!=null?(service.currency||"")+" "+Number(service.price_amount).toLocaleString()+" · "+service.pricing_model:service.pricing_model;}
type ServiceRequest={id:string;service_listing_id?:string;status:string;idempotent?:boolean;tracking_reference?:string;service_title?:string;created_at?:string;message?:string;provider_user_id?:string;requester_user_id?:string;is_provider?:boolean;provider_completed_at?:string|null;provider_completion_submitted_by?:string|null;requester_accepted_at?:string|null;requester_outcome_decision?:string|null;requester_outcome_decision_at?:string|null;final_outcome_summary?:string|null;outcome_summary?:string|null;nextAction?:string;agreement_terms_version?:number;agreement_terms?:{scope?:string|null;listingPricingModel?:string|null;listingPriceAmount?:number|null;listingCurrency?:string|null;agreedPrice?:number|null;currency?:string|null;completionDueAt?:string|null;requestedStartAt?:string|null;requestedEndAt?:string|null}|null;agreement_provider_accepted_at?:string|null;agreement_requester_accepted_at?:string|null;status_history?:{fromStatus?:string|null;toStatus?:string|null;note?:string|null;createdAt?:string}[];completion_history?:{eventType:string;actorUserId?:string;note?:string|null;createdAt?:string;outcomeSummary?:string|null}[]};
